use mabi_meter_core::{capture_file::Input,identity::{Appearance,EntityKey},meter::{Action,Command},protocol,replay::Replay,session::Session,transport::{Flow,Segment}};
fn put(p:&mut[u8],o:usize,n:u64){p[o..o+8].copy_from_slice(&n.to_le_bytes());}
fn frame(w:i32,p:&[u8])->Vec<u8>{protocol::encode_frame(w,p)}
fn feed(r:&mut Replay,seq:&mut u32,w:i32,p:Vec<u8>,t:u64){let payload=frame(w,&p);let n=payload.len()as u32;r.feed(Input::Segment(Segment{timestamp_ns:t,flow:Flow{src:"192.0.2.1".into(),dst:"192.0.2.2".into(),sport:15000,dport:16000},seq:*seq,payload,syn:false,fin:false,rst:false,ack:true})).unwrap();*seq+=n;}
fn hp(r:&mut Replay,seq:&mut u32,actor:u64,n:u64,t:u64){let mut p=vec![0;21];put(&mut p,0,actor);p[8..12].copy_from_slice(&8u32.to_le_bytes());put(&mut p,12,n);feed(r,seq,170205,p,t);}
fn damage(r:&mut Replay,seq:&mut u32,actor:u64,target:u64,raw:u64,aux:u64,t:u64){let mut p=vec![0;53];put(&mut p,0,actor);put(&mut p,8,target);put(&mut p,16,raw);put(&mut p,24,aux);feed(r,seq,21196,p,t);}
fn attack(r:&mut Replay,seq:&mut u32,actor:u64,target:u64,t:u64){let mut p=vec![0;35];put(&mut p,0,actor);put(&mut p,8,target);p[16..20].copy_from_slice(&77u32.to_le_bytes());feed(r,seq,20526,p,t);}
fn roster(r:&mut Replay,actor:u32)->EntityKey{r.meter.registry.appearance(0,r.meter.binding,Appearance{actor,name:format!("actor{actor}"),uid:Some(100000+actor as u64),template:None,offset:0,record_reference:None}).unwrap()}
fn replay()->Replay{let mut r=Replay::new(true);r.live_scope=true;r}
fn invariant(r:&Replay){let a=r.health.attribution.audit();assert_eq!(a["invariant"],true,"{a}");assert_eq!(r.health.unassigned,r.health.attribution.unattributed_inferred);}
#[test]fn distinct_wide_target_initials_cannot_manufacture_damage(){let mut r=replay();let mut seq=1;roster(&mut r,1);hp(&mut r,&mut seq,u32::MAX as u64+1,100,0);hp(&mut r,&mut seq,u32::MAX as u64+2,90,0);r.finish();invariant(&r);assert_eq!(r.numeric.detected,0);assert_eq!(r.health.loss,0);assert_eq!(r.meter.session.estimated_total.damage,0);}
#[test]fn full_identity_registry_uses_bounded_roster_and_keeps_new_numeric_damage(){
    let mut r=replay();for actor in 1..=32768{r.meter.registry.observe(0,1,actor).unwrap();}
    let mut seq=1;let began=std::time::Instant::now();hp(&mut r,&mut seq,300000,100,0);let refresh=began.elapsed();hp(&mut r,&mut seq,300000,50,0);r.finish();invariant(&r);
    assert_eq!(r.numeric.detected,50);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,50);assert!(r.health.attribution.audit()["actors"].as_u64().unwrap()<=512);assert_eq!(r.assignment_storage()["within_budget"],true);
    println!("full32768registry_bounded512roster_refresh_ns={}",refresh.as_nanos());
}
#[test]fn source_capacity_routes_through_same_fallback_and_does_not_block_later_actors(){
    use mabi_meter_core::meter::Hit;let mut r=replay();let target=EntityKey{process:0,binding:1,actor:999999,generation:0};
    for actor in 1..=32768{let source=if actor==1{r.meter.registry.observe(0,1,actor).unwrap()}else{EntityKey{actor,..target}};r.meter.add(Hit{timestamp_ns:0,source,target,damage:protocol::Damage{actor,target:target.actor,amount:0,flags:[false;5],raw_flags:[0;7]}}).unwrap();}
    let mut seq=1;damage(&mut r,&mut seq,32769,999999,11,0,0);damage(&mut r,&mut seq,1,999999,22,0,0);r.finish();invariant(&r);assert_eq!(r.meter.session.total.damage,22);assert_eq!(r.health.attribution.unattributed_explicit,11);assert_eq!(r.health.attribution.queued_amount(),0);assert_eq!(r.health.attribution.owed_amount(),0);assert!(r.diagnostics.0["credit_source_capacity_forced_inference"]>0);
}
#[test]fn no_presentation_rejects_cold_roster_without_self_privilege(){
    let mut amounts=Vec::new();for selected in [None,Some(1),Some(2)]{let mut r=replay();let mut seq=1;let a=roster(&mut r,1);let b=roster(&mut r,2);r.meter.registry.assign(selected.map(|n|if n==1{a}else{b})).unwrap();hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,90,0);r.finish();invariant(&r);let x:Vec<_>=r.meter.session.estimates.iter().map(|(k,v)|(k.actor,v.damage)).collect();assert_eq!(x.iter().map(|(_,n)|*n).sum::<u128>(),0);assert_eq!(r.health.unassigned,10);amounts.push(x);}assert_eq!(amounts[0],amounts[1]);assert_eq!(amounts[0],amounts[2]);
}
#[test]fn partial_explicit_keeps_residual_unattributed_without_peer_support(){let mut r=replay();let mut seq=1;hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,90,0);attack(&mut r,&mut seq,1,99,0);damage(&mut r,&mut seq,1,99,4,0,0);r.finish();invariant(&r);assert_eq!(r.meter.session.total.damage,4);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,6);}
#[test]fn zero_exact_component_does_not_remove_a_detected_budget(){let mut r=replay();let mut seq=1;hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,90,0);attack(&mut r,&mut seq,1,99,0);damage(&mut r,&mut seq,1,99,0,0,0);r.finish();invariant(&r);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,10);}
#[test]fn metadata_failure_cannot_drop_later_damage_in_same_extracted_batch(){
    use mabi_meter_core::combat::{Effect,Stamp};let mut r=replay();let me=roster(&mut r,1);let at=Stamp{process:0,continuity:0,context:1,frame:0,order:0,timestamp_ns:0,tcp_byte:0};for instance in 1..=32768{r.combat.effect(Effect{affected:me,instance,id:1,time_bits:0,stacks:1,source:None,first:at,last:at}).unwrap();}
    let mut e=vec![0;36];put(&mut e,0,1);put(&mut e,8,32769);e[16..20].copy_from_slice(&1u32.to_le_bytes());let mut d=vec![0;53];put(&mut d,0,1);put(&mut d,8,99);put(&mut d,16,957);put(&mut d,24,915);let mut bytes=frame(170069,&e);bytes.extend(frame(21196,&d));r.feed(Input::Segment(Segment{timestamp_ns:0,flow:Flow{src:"192.0.2.1".into(),dst:"192.0.2.2".into(),sport:15000,dport:16000},seq:1,payload:bytes,syn:false,fin:false,rst:false,ack:true})).unwrap();r.finish();invariant(&r);assert_eq!(r.meter.session.total.damage,957);assert!(r.semantic_error.is_none());
}
#[test]fn gap_and_opaque_numeric_decreases_reach_same_fallback(){for opaque in [false,true]{let mut r=replay();let mut seq=1;roster(&mut r,1);hp(&mut r,&mut seq,99,100,0);if opaque{let mut bytes=vec![];bytes.extend(21231u32.to_le_bytes());bytes.extend(4u32.to_le_bytes());bytes.push(1);bytes.extend([255;4]);let n=bytes.len()as u32;r.feed(Input::Segment(Segment{timestamp_ns:1,flow:Flow{src:"192.0.2.1".into(),dst:"192.0.2.2".into(),sport:15000,dport:16000},seq,payload:bytes,syn:false,fin:false,rst:false,ack:true})).unwrap();seq+=n;}else{r.feed(Input::Loss{code:"testgap".into(),reset:false}).unwrap();}hp(&mut r,&mut seq,99,50,2);r.finish();invariant(&r);assert_eq!(r.numeric.detected,50);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,50);}}
#[test]fn maximum_hp_is_not_damage_but_finite_endpoint_obligations_survive(){let mut r=replay();let mut seq=1;roster(&mut r,1);hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,i64::MAX as u64,0);hp(&mut r,&mut seq,99,90,0);r.finish();invariant(&r);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,10);}
#[test]fn no_actor_after_eof_stays_unattributed_despite_later_presence(){let mut r=replay();let mut seq=1;hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,90,0);r.finish();assert_eq!(r.health.attribution.owed_amount(),0);assert_eq!(r.health.unassigned,10);let source=EntityKey{process:0,binding:1,actor:1,generation:1};let at=mabi_meter_core::combat::Stamp{process:0,continuity:0,context:2,frame:100,order:100,timestamp_ns:1,tcp_byte:0};r.health.note_actor_kind(source,"player",at);r.finish();r.finish();invariant(&r);assert_eq!(r.meter.session.estimated_total.damage,0);assert_eq!(r.health.unassigned,10);assert_eq!(r.health.attribution.owed_amount(),0);}
#[test]fn failed_consumer_retains_all_leases_and_retry_is_exact_once(){let mut r=replay();let mut seq=1;r.meter.session.total.damage=u128::MAX;damage(&mut r,&mut seq,1,99,11,0,0);damage(&mut r,&mut seq,2,99,22,0,0);r.finish();assert_eq!(r.health.attribution.queued_amount(),33);assert_eq!(r.meter.session.sources.len(),0);r.meter.session.total.damage=0;r.retry_pending_credits().unwrap();r.retry_pending_credits().unwrap();invariant(&r);assert_eq!(r.meter.session.total.damage,33);assert_eq!(r.health.attribution.queued_amount(),0);}
#[test]fn equal_actor_is_rejected_without_discarding_raw_evidence(){let mut r=replay();let mut seq=1;damage(&mut r,&mut seq,1,1,1_000_000_000_001,0,0);r.finish();invariant(&r);assert_eq!(r.meter.session.total.damage,0);assert_eq!(r.health.attribution.unattributed_explicit,1_000_000_000_001);}
#[test]fn reset_credit_is_delivered_before_boundary_and_no_terminal_sink(){let mut r=replay();let mut seq=1;roster(&mut r,1);hp(&mut r,&mut seq,99,100,0);hp(&mut r,&mut seq,99,90,0);attack(&mut r,&mut seq,1,99,0);let mut s=Session::new(r,None);let c=Command{id:1,encounter:1,observed_revision:s.replay.meter.revision,action:Action::Reset};assert!(s.command(c).applied);assert_eq!(s.replay.meter.encounters[&1].views[&None].estimated_total.damage,10);assert_eq!(s.replay.meter.snapshot().summary.damage,0);invariant(&s.replay);}
